
(()=>{'use strict';const D=window.COURSE_DATA,DICT=window.COURSE_DICTIONARY,P=window.ADMIN_PROMPTS,C=window.APP_CONFIG;const SKEY='ep-state-v1',PACKKEY='ep-content-packs-v1',DB='ep-audio-v1',STORE='audio';applyContentPacks();const $=id=>document.getElementById(id);const screen=$('screen'),drawer=$('drawer'),popup=$('popup'),modal=$('modal'),toast=$('toast');let state=load(),view='dashboard',selection=state.level||'A1',admin=false,exam=null,timer=null;
function fresh(){return{onboarded:false,profile:{name:'',email:'',purpose:'General English'},level:'A1',unlocked:['A1'],current:'A1-U1-D1',progress:{},vocab:[],notes:{},exams:{},theme:'light',wordHelp:true,endpoint:C.teacherEndpoint||'',recommendation:null,activity:[]}}
function contentPacks(){try{const a=JSON.parse(localStorage.getItem(PACKKEY)||'[]');return Array.isArray(a)?a:[]}catch(e){return[]}}
function applyContentPacks(){for(const pack of contentPacks()){if(pack?.platform!=='English Pathways')continue;for(const item of(pack.addedUnits||[])){const l=D.levels.find(x=>x.id===item.levelId);if(!l)continue;const ids=new Set(l.units.map(u=>u.id));for(const u of(item.units||[])){if(!ids.has(u.id)){l.units.push(u);ids.add(u.id)}}l.units.sort((a,b)=>(a.number||0)-(b.number||0))}for(const item of(pack.replaceUnits||[])){const l=D.levels.find(x=>x.id===item.levelId);if(!l)continue;for(const u of(item.units||[])){const i=l.units.findIndex(x=>x.id===u.id);if(i>=0)l.units[i]=u;else l.units.push(u)}l.units.sort((a,b)=>(a.number||0)-(b.number||0))}if(pack.dictionary&&typeof pack.dictionary==='object')Object.assign(DICT,pack.dictionary)}D.lessonCount=D.levels.reduce((n,l)=>n+l.units.reduce((m,u)=>m+u.lessons.length,0),0)}
function compareVersions(a,b){const pa=String(a||'0').split('.').map(Number),pb=String(b||'0').split('.').map(Number);for(let i=0;i<Math.max(pa.length,pb.length);i++){const x=pa[i]||0,y=pb[i]||0;if(x>y)return 1;if(x<y)return-1}return 0}
function load(){try{const s={...fresh(),...(JSON.parse(localStorage.getItem(SKEY)||'null')||{})};if(!s.endpoint&&C.teacherEndpoint)s.endpoint=C.teacherEndpoint;return s}catch(e){return fresh()}}function save(){localStorage.setItem(SKEY,JSON.stringify(state))}function esc(s=''){return String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}function say(m){toast.textContent=m;toast.classList.add('show');clearTimeout(say.t);say.t=setTimeout(()=>toast.classList.remove('show'),2300)}function log(t,d={}){state.activity.push({t,d,at:new Date().toISOString()});save()}function level(id){return D.levels.find(x=>x.id===id)||D.levels[0]}function idx(id){return D.levels.findIndex(x=>x.id===id)}function lessons(id=null){return(id?[level(id)]:D.levels).flatMap(l=>l.units.flatMap(u=>u.lessons.map(x=>({...x,levelId:l.id,unitTitle:u.title}))))}function findLesson(id){return lessons().find(x=>x.id===id)||lessons()[0]}function lp(id){if(!state.progress[id])state.progress[id]={done:false,quiz:{},writing:'',homework:'',step:0};return state.progress[id]}function prog(id){const a=lessons(id),n=a.filter(x=>state.progress[x.id]?.done).length;return{n,total:a.length,p:a.length?Math.round(n/a.length*100):0}}function unlocked(id){return state.unlocked.includes(id)}function words(s){return String(s).trim()?String(s).trim().split(/\s+/).length:0}function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},800)}function safe(s){return String(s||'student').replace(/[^a-z0-9_-]+/gi,'_')}function theme(){document.documentElement.dataset.theme=state.theme}theme();
$('homeBtn')&&($('homeBtn').onclick=()=>go('dashboard'));$('courseBtn')&&($('courseBtn').onclick=()=>go('course'));$('dictBtn')&&($('dictBtn').onclick=openDictionary);$('updateBtn')&&($('updateBtn').onclick=()=>go('updates'));$('adminBtn')&&($('adminBtn').onclick=gate);$('themeBtn')&&($('themeBtn').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';theme();save()});
function announceView(v){document.body.dataset.view=v;window.dispatchEvent(new CustomEvent('ep:viewchange',{detail:{view:v}}))}function go(v,p={}){clearInterval(timer);view=v;announceView(v);drawer.classList.remove('open');popup.hidden=true;if(v==='dashboard')dashboard();if(v==='course'){if(p.level)selection=p.level;course()}if(v==='lesson')lessonView(p.id||state.current);if(v==='vocab')vocabView();if(v==='progress')progressView();if(v==='more')moreView();if(v==='exam')examStart(p.level||state.level);if(v==='updates')updatesView();if(v==='admin')adminView(p.tab||'overview')}
function render(){state.onboarded?go('dashboard'):onboard()}
function onboard(){announceView('onboard');screen.innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">Complete English pathway</div><h1>Learn every day and keep every result.</h1><p class="lead">A structured A1–C2 programme with lessons, voice practice, homework, dictionary help and examinations.</p><form id="form" class="formgrid"><div class="field"><label>Name</label><input id="name" required></div><div class="field"><label>Email</label><input id="email" type="email"></div><div class="field"><label>Starting level</label><select id="start">${D.levels.map(l=>`<option value="${l.id}">${l.cefr} — ${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Purpose</label><select id="purpose"><option>General English</option><option>Employment</option><option>Teaching</option><option>Academic study</option></select></div><div class="full notice">Placement is optional. Your teacher can recommend or change the starting level later.</div><div class="full"><button class="primary">Create profile</button></div></form></section></div>`;document.getElementById('form').onsubmit=e=>{e.preventDefault();state.profile={name:$('name').value.trim(),email:$('email').value.trim(),purpose:$('purpose').value};state.level=$('start').value;state.unlocked=D.levels.slice(0,idx(state.level)+1).map(l=>l.id);state.current=level(state.level).units[0].lessons[0].id;state.onboarded=true;save();dashboard()}}
function dashboard(){announceView('dashboard');const l=level(state.level),p=prog(l.id),cur=findLesson(state.current);screen.innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">Welcome back, ${esc(state.profile.name)}</div><h1>Your English pathway continues here.</h1><p class="lead">${esc(l.description)}</p><div class="buttons"><button class="primary" id="continue">Continue: ${esc(cur.title)}</button><button class="secondary" id="browse">Browse course</button><button class="ghost" id="placement">Placement test</button></div></section><div class="metrics"><div class="metric"><small>Current level</small><strong>${l.cefr}</strong></div><div class="metric"><small>Course progress</small><strong>${p.p}%</strong></div><div class="metric"><small>Lessons complete</small><strong>${p.n}/${p.total}</strong></div><div class="metric"><small>Saved words</small><strong>${state.vocab.length}</strong></div></div><div class="grid2"><section class="card"><h2>Daily routine</h2><div class="grid3" style="margin-top:15px"><div class="notice"><b>Review</b><br><small>Previous errors and vocabulary</small></div><div class="notice"><b>Learn</b><br><small>Grammar, reading or listening</small></div><div class="notice"><b>Produce</b><br><small>Speaking, writing and quiz</small></div></div><div class="progress" style="margin-top:18px"><div style="width:${p.p}%"></div></div></section><section class="card"><h2>Quick tools</h2><div class="sideList"><button class="sideItem" id="qd">Dictionary and Word Help</button><button class="sideItem" id="qv">Vocabulary notebook</button><button class="sideItem" id="qe">End-of-level exam</button><button class="sideItem" id="qu">Install course update</button><button class="sideItem" id="qb">Export progress backup</button></div></section></div></div>`;document.getElementById('continue').onclick=()=>go('lesson',{id:state.current});document.getElementById('browse').onclick=()=>go('course');document.getElementById('placement').onclick=()=>window.open('placement-test/index.html','_blank');document.getElementById('qd').onclick=openDictionary;document.getElementById('qv').onclick=()=>go('vocab');document.getElementById('qe').onclick=()=>go('exam',{level:state.level});document.getElementById('qu').onclick=()=>go('updates');document.getElementById('qb').onclick=exportBackup}
function course(){announceView('course');const l=level(selection);screen.innerHTML=`<div class="shell"><div class="courseLayout"><aside class="sidebar"><div class="eyebrow">Course levels</div><div class="sideList">${D.levels.map(x=>`<button class="sideItem ${x.id===selection?'active':''}" data-level="${x.id}">${x.cefr} — ${esc(x.name)} ${unlocked(x.id)?'':'• Preview'}</button>`).join('')}</div></aside><div><section class="hero"><div class="eyebrow">${l.cefr} course</div><h1>${esc(l.name)}</h1><p class="lead">${esc(l.description)}</p><div class="metrics"><div class="metric"><small>Units</small><strong>${l.units.length}</strong></div><div class="metric"><small>Lessons</small><strong>${lessons(l.id).length}</strong></div><div class="metric"><small>Progress</small><strong>${prog(l.id).p}%</strong></div><div class="metric"><small>Status</small><strong style="font-size:16px">${unlocked(l.id)?'Open':'Preview'}</strong></div></div></section><div style="margin-top:16px">${l.units.map(u=>`<section class="unit"><div class="unitHead richUnitHead"><div><div class="eyebrow">Unit ${u.number}</div><h2>${esc(u.title)}</h2><small>${esc(u.theme)}</small><p class="unitTopic">${esc(u.topicTitle||"")}</p></div>${u.illustration?`<img class="unitThumb" src="${esc(u.illustration)}" alt="Illustration for ${esc(u.topicTitle||u.title)}">`:""}</div>${u.lessons.map((x,i)=>{const p=lp(x.id),open=unlocked(l.id)||i===0;return`<div class="lessonRow ${p.done?'done':''}"><div class="num">${p.done?'✓':x.day}</div><div><b>${esc(x.title)}</b><br><small>${x.minutes} min • ${esc(x.subtitle)}</small></div><button class="${open?'secondary':'ghost'}" data-lesson="${x.id}" ${open?'':'disabled'}>${p.done?'Review':'Open'}</button></div>`}).join('')}</section>`).join('')}<div class="buttons"><button class="primary" id="examBtn">Open ${l.cefr} end-of-level exam</button></div></div></div></div></div>`;document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{selection=b.dataset.level;course()});document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>go('lesson',{id:b.dataset.lesson}));$('examBtn').onclick=()=>go('exam',{level:l.id})}
function helpText(t){if(!state.wordHelp)return esc(t);let s=esc(t);Object.keys(DICT).filter(k=>!k.includes(' ')).sort((a,b)=>b.length-a.length).slice(0,500).forEach(k=>{const r=new RegExp(`\\b(${k.replace(/[.*+?^${}()|[\\]\\]/g,'\\$&')})\\b`,'gi');s=s.replace(r,'<span class="helpWord" data-word="$1">$1</span>')});return s}
function paras(t){return String(t||'').split(/\n\s*\n/).filter(Boolean).map(x=>`<p>${helpText(x)}</p>`).join('')}function bulletList(a,cls='activityList'){return`<ul class="${cls}">${(a||[]).map(x=>`<li>${helpText(x)}</li>`).join('')}</ul>`}function ill(x,compact=false){return x.illustration?`<figure class="lessonIllustration ${compact?'compact':''}"><img src="${esc(x.illustration)}" alt="Original illustration for ${esc(x.topicTitle||x.unitTitle||'the lesson')}"><figcaption>${esc(x.topicTitle||'Real-world lesson')}</figcaption></figure>`:''}function dialogue(a){return`<div class="dialogue">${(a||[]).map((x,i)=>`<p><b>${i%2?'B':'A'}:</b> ${helpText(String(x).replace(/^[AB]:\s*/,''))}</p>`).join('')}</div>`}
function lessonView(id){announceView('lesson');const x=findLesson(id),p=lp(id);state.current=id;state.level=x.levelId;save();let body='';const hero=ill(x);if(x.day===1)body=`${hero}<div class="topicRibbon"><span>${esc(x.topicTitle||x.unitTitle)}</span><small>${esc(x.hook||'')}</small></div><div class="eyebrow">Core language</div><h2>${esc(x.grammar.title)}</h2><div class="languageBox"><p>${helpText(x.grammar.rule)}</p>${x.grammar.examples.map(e=>`<p><b>Example:</b> ${helpText(e)}</p>`).join('')}</div><div class="grid2 lessonSplit"><section><h3>Vocabulary in context</h3><div class="vocabGrid">${x.vocab.map(v=>`<div class="vocab"><div><strong class="helpWord" data-word="${esc(v.word)}">${esc(v.word)}</strong> <span class="posTag">${esc(v.pos||'word')}</span></div><p>${esc(v.definition)}</p></div>`).join('')}</div></section><section><h3>Mini-dialogue</h3>${dialogue(x.miniDialogue)}<h3>Phrasal verbs and expressions</h3><div class="vocabGrid oneCol">${x.phrasal.map(v=>`<div class="vocab"><strong class="helpWord" data-word="${esc(v.word)}">${esc(v.word)}</strong><p>${esc(v.definition)}</p></div>`).join('')}</div></section></div><div class="factCard"><b>Real-world connection</b><p>${helpText(x.fact)}</p></div>`;if(x.day===2)body=`${hero}<div class="eyebrow">Reading and use of English</div><h2>${esc(x.readingTitle)}</h2><div class="readingBox">${paras(x.reading)}</div><div class="grid2 lessonSplit"><div class="factCard"><b>Did you know?</b><p>${helpText(x.fact)}</p></div><div class="challengeCard"><b>Think and apply</b><p>${helpText(x.realWorldTask)}</p></div></div><h3>Read actively</h3><p class="aiIntro">Answer in your own words. <b>Check with AI</b> judges meaning as well as language, so a correct paraphrase can receive credit.</p>${aiPracticeBlock(x,p,'reading',x.readingQuestions,x.reading)}${quizBlock(x,p,'reading')}`;if(x.day===3)body=`${hero}<div class="eyebrow">Listening and pronunciation</div><h2>${esc(x.topicTitle||'Listen for meaning')}</h2><div class="languageBox"><p>Listen once for the main idea. Replay for details. Answer the questions <b>before</b> opening the transcript whenever possible.</p><div class="buttons"><button class="primary" id="listen">Play listening</button><button class="ghost" id="stopVoice">Stop</button></div><details><summary>Transcript — open after listening</summary>${paras(x.listening)}</details></div><h3>Listening comprehension</h3><p class="aiIntro">Write short answers in your own words, then use <b>Check with AI</b>. The AI checks comprehension separately from grammar.</p>${aiPracticeBlock(x,p,'listening',listeningPrompts(),x.listening)}<div class="grid2 lessonSplit"><div class="pronunciationCard"><b>Pronunciation focus</b><p>${esc(x.pronunciationFocus)}</p><ol><li>Listen to one sentence.</li><li>Pause and repeat with the same thought groups.</li><li>Record a final version without reading too quickly.</li></ol></div><div class="factCard"><b>Listening strategy</b><p>Do not try to catch every word. Identify the speaker’s purpose, the key contrast and the requested next step.</p></div></div>${recordBox(x.id+'-pronunciation','Read the grammar examples or one short section of the transcript. Focus on '+x.pronunciationFocus+'.')}`;if(x.day===4)body=`${hero}<div class="eyebrow">Speaking and functional English</div><h2>Real-world speaking challenge</h2><div class="challengeCard large"><b>${esc(x.topicTitle)}</b><p>${helpText(x.speaking)}</p></div><div class="grid2 lessonSplit"><section><h3>Useful language</h3>${bulletList(x.usefulPhrases)}</section><section><h3>Three-step plan</h3>${bulletList(x.speakingSteps)}</section></div>${recordBox(x.id+'-speaking','Plan briefly, speak naturally, listen once and improve one specific feature rather than recording repeatedly without a goal.')}`;if(x.day===5)body=`${hero}<div class="eyebrow">Writing, review and homework</div><h2>Write for a real purpose</h2><div class="challengeCard"><b>Writing brief</b><p>${helpText(x.writing)}</p></div><div class="grid2 lessonSplit"><div class="writingBox"><textarea id="writing" placeholder="Write your response here…">${esc(p.writing||'')}</textarea><small id="wc">${words(p.writing||'')} words</small></div><div><h3>Quality checklist</h3>${bulletList(x.writingChecklist)}<div class="factCard"><b>Mini-project</b><p>${helpText(x.homework)}</p></div></div></div><div class="writingBox"><textarea id="homework" placeholder="Record notes, observations or project evidence here…">${esc(p.homework||'')}</textarea></div>${quizBlock(x,p,'final')}`;screen.innerHTML=`<div class="shell"><div class="lessonLayout"><aside class="sidebar"><div class="eyebrow">${level(x.levelId).cefr} • ${esc(x.unitTitle)}</div><h3 style="margin-top:8px">Day ${x.day} of 5</h3><div class="progress" style="margin-top:14px"><div style="width:${x.day*20}%"></div></div><div class="sideList"><button class="sideItem" id="courseBack">Course map</button><button class="sideItem" id="wordToggle">Word Help: ${state.wordHelp?'On':'Off'}</button><button class="sideItem" id="dictOpen">Dictionary</button></div><div class="sidebarTip"><b>Today’s context</b><p>${esc(x.topicTitle||x.unitTitle)}</p></div></aside><article class="lesson"><header class="lessonHead"><div class="eyebrow">${esc(x.type)}</div><h2>${esc(x.title)}</h2><small>${x.minutes} minutes • saved locally</small></header><div class="lessonBody">${body}</div><footer class="lessonFoot"><button class="ghost" id="prevLesson">Previous lesson</button><div class="buttons" style="margin:0"><button class="secondary" id="saveLesson">Save</button><button class="primary" id="completeLesson">${p.done?'Completed':'Complete lesson'}</button></div></footer></article></div></div>`;bindHelp();$('courseBack').onclick=()=>go('course');$('dictOpen').onclick=openDictionary;$('wordToggle').onclick=()=>{state.wordHelp=!state.wordHelp;save();lessonView(id)};const list=lessons(),i=list.findIndex(a=>a.id===id);$('prevLesson').disabled=i<=0;$('prevLesson').onclick=()=>go('lesson',{id:list[i-1].id});$('saveLesson').onclick=()=>capture(x,p);$('completeLesson').onclick=()=>{capture(x,p);p.done=true;const n=list[i+1];if(n)state.current=n.id;log('lesson-complete',{id});say('Lesson completed.');setTimeout(dashboard,350)};if(x.day===3){$('listen').onclick=()=>speak(x.listening);$('stopVoice').onclick=()=>speechSynthesis.cancel();bindRecord(document.querySelector('.recordBox'))}if(x.day===4)bindRecord(document.querySelector('.recordBox'));if(x.day===5){$('writing').oninput=()=>{p.writing=$('writing').value;$('wc').textContent=words($('writing').value)+' words';save()};$('homework').oninput=()=>{p.homework=$('homework').value;save()}}bindQuiz(x,p);bindAIPractice(x,p)}
function listeningPrompts(){return['Who are the speakers, or what roles do they have?','What is the main situation or purpose of the conversation?','What action or next step is suggested?','What does one speaker ask to be repeated or clarified?']}
function aiPracticeBlock(x,p,skill,questions,evidence){p.ai=p.ai||{};if(!C.aiEndpoint)return`<div class="notice warn">AI checking is not configured yet.</div>`;return`<div class="aiPractice" data-ai-skill="${esc(skill)}" data-ai-evidence="${esc(evidence||'')}">${(questions||[]).map((q,i)=>{const k=skill+i,a=p.ai[k]?.answer||'',g=p.ai[k]?.grading;return`<div class="aiQuestion" data-ai-index="${i}"><label for="ai-${skill}-${i}"><b>${i+1}. ${esc(q)}</b></label><textarea id="ai-${skill}-${i}" class="aiAnswer" rows="3" placeholder="Type your answer in your own words…">${esc(a)}</textarea><div class="buttons aiButtons"><button type="button" class="secondary aiCheck" data-ai-key="${esc(k)}">Check with AI</button><button type="button" class="ghost aiClear" data-ai-key="${esc(k)}">Clear</button></div><div class="aiFeedback" aria-live="polite">${g?aiFeedbackHtml(g):''}</div></div>`}).join('')}</div>`}
function aiFeedbackHtml(g){const r=g.result==='correct'?'Correct':g.result==='partly_correct'?'Partly correct':'Needs another try',cls=g.result==='correct'?'good':g.result==='partly_correct'?'partial':'bad',score=Number.isFinite(Number(g.score))&&Number.isFinite(Number(g.maxScore))?`<span class="aiScore">${esc(g.score)}/${esc(g.maxScore)}</span>`:'';return`<div class="aiResult ${cls}"><div class="aiResultHead"><strong>${r}</strong>${score}</div><div class="aiChecks"><span>${g.comprehensionCorrect?'✓':'○'} Understanding</span><span>${g.languageCorrect?'✓':'○'} English accuracy</span></div>${g.feedback?`<p><b>Feedback:</b> ${esc(g.feedback)}</p>`:''}${g.languageFeedback?`<p><b>English:</b> ${esc(g.languageFeedback)}</p>`:''}${g.improvedAnswer?`<p><b>Better answer:</b> ${esc(g.improvedAnswer)}</p>`:''}${g.hint&&g.canRetry?`<p class="aiHint"><b>Hint:</b> ${esc(g.hint)}</p>`:''}</div>`}
function aiJsonp(params){return new Promise((resolve,reject)=>{const endpoint=String(C.aiEndpoint||'').trim();if(!endpoint)return reject(new Error('AI endpoint is not configured.'));if(!navigator.onLine)return reject(new Error('Connect to the internet to use AI checking.'));const cb='epAI_'+Date.now()+'_'+Math.random().toString(36).slice(2),script=document.createElement('script');let finished=false;const cleanup=()=>{if(finished)return;finished=true;clearTimeout(timer);try{delete window[cb]}catch(e){window[cb]=undefined}script.remove()};window[cb]=data=>{cleanup();resolve(data)};script.onerror=()=>{cleanup();reject(new Error('The AI service could not be reached.'))};const q=new URLSearchParams({...params,action:'grade',prefix:cb});script.src=endpoint+(endpoint.includes('?')?'&':'?')+q.toString();script.async=true;document.body.appendChild(script);const timer=setTimeout(()=>{cleanup();reject(new Error('The AI check took too long. Try again.'))},30000)})}
function bindAIPractice(x,p){document.querySelectorAll('.aiPractice').forEach(block=>{const skill=block.dataset.aiSkill,evidence=block.dataset.aiEvidence||'';block.querySelectorAll('.aiQuestion').forEach(card=>{const i=Number(card.dataset.aiIndex),question=(skill==='reading'?x.readingQuestions:listeningPrompts())[i]||'',area=card.querySelector('.aiAnswer'),check=card.querySelector('.aiCheck'),clear=card.querySelector('.aiClear'),feedback=card.querySelector('.aiFeedback'),key=check.dataset.aiKey;p.ai=p.ai||{};area.oninput=()=>{p.ai[key]=p.ai[key]||{};p.ai[key].answer=area.value;save()};clear.onclick=()=>{area.value='';p.ai[key]={answer:''};feedback.innerHTML='';save()};check.onclick=async()=>{const answer=area.value.trim();if(!answer)return say('Write an answer first.');check.disabled=true;const old=check.textContent;check.textContent='Checking…';feedback.innerHTML='<div class="aiWaiting">Checking meaning and English…</div>';try{const data=await aiJsonp({level:level(x.levelId).cefr,skill:skill==='reading'?'Reading':'Listening',question,expectedAnswer:'',evidence:String(evidence).slice(0,3500),studentAnswer:answer});if(!data?.ok)throw new Error(data?.error||'AI grading failed.');p.ai[key]={answer,grading:data.grading,checkedAt:new Date().toISOString()};save();feedback.innerHTML=aiFeedbackHtml(data.grading)}catch(err){feedback.innerHTML=`<div class="aiResult bad"><strong>Could not check this answer.</strong><p>${esc(err.message||err)}</p></div>`}finally{check.disabled=false;check.textContent=old}}})})}
function quizBlock(x,p,key){return`<h3 style="margin-top:18px">Checkpoint</h3>${x.quiz.map((q,i)=>`<div class="quizItem"><b>${i+1}. ${esc(q.prompt)}</b><div class="options">${q.options.map((o,j)=>`<label class="option"><input type="radio" name="${key}${i}" value="${j}" ${p.quiz[key+i]===j?'checked':''}><span><b>${String.fromCharCode(65+j)}.</b> ${esc(o)}</span></label>`).join('')}</div><div id="fb${key}${i}"></div></div>`).join('')}<button class="secondary checkQuiz" data-key="${key}">Check answers</button>`}
function bindQuiz(x,p){document.querySelectorAll('.checkQuiz').forEach(b=>b.onclick=()=>{const key=b.dataset.key;x.quiz.forEach((q,i)=>{const r=document.querySelector(`input[name="${key}${i}"]:checked`),v=r?Number(r.value):null;p.quiz[key+i]=v;document.getElementById('fb'+key+i).innerHTML=v===q.answer?`<div class="feedback good">Correct. ${esc(q.explanation)}</div>`:`<div class="feedback bad">Review this item. ${esc(q.explanation)}</div>`});save()})}
function capture(x,p){if($('writing'))p.writing=$('writing').value;if($('homework'))p.homework=$('homework').value;save();say('Progress saved.')}
function speak(t){if(!speechSynthesis)return say('Speech synthesis is unavailable.');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='en-GB';u.rate=.9;speechSynthesis.speak(u)}
function recordBox(k,t){return`<div class="recordBox" data-key="${esc(k)}"><div class="recordPulse">Recording now</div><p>${esc(t)}</p><div class="buttons"><button class="primary startRec">● Record</button><button class="ghost stopRec" disabled>■ Stop</button><button class="ghost playRec" disabled>▶ Play</button><button class="danger delRec" disabled>Delete</button></div><audio controls hidden></audio><small class="status">No recording loaded.</small></div>`}
function db(){return new Promise((ok,no)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE)};r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}async function put(k,b){const d=await db();return new Promise((ok,no)=>{const t=d.transaction(STORE,'readwrite');t.objectStore(STORE).put(b,k);t.oncomplete=ok;t.onerror=()=>no(t.error)})}async function get(k){try{const d=await db();return await new Promise((ok,no)=>{const t=d.transaction(STORE);const r=t.objectStore(STORE).get(k);r.onsuccess=()=>ok(r.result||null);r.onerror=()=>no(r.error)})}catch(e){return null}}async function del(k){const d=await db();return new Promise(ok=>{const t=d.transaction(STORE,'readwrite');t.objectStore(STORE).delete(k);t.oncomplete=ok})}async function keys(){const d=await db();return new Promise(ok=>{const t=d.transaction(STORE);const r=t.objectStore(STORE).getAllKeys();r.onsuccess=()=>ok(r.result||[])})}
async function bindRecord(box){const k=box.dataset.key,a=box.querySelector('audio'),st=box.querySelector('.startRec'),sp=box.querySelector('.stopRec'),pl=box.querySelector('.playRec'),de=box.querySelector('.delRec'),status=box.querySelector('.status');let old=await get(k);if(old){a.src=URL.createObjectURL(old);a.hidden=false;pl.disabled=false;de.disabled=false;status.textContent='Saved recording loaded.'}let rec,stream,chunks=[];st.onclick=async()=>{try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Recording is not supported in this browser.');stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});chunks=[];rec=new MediaRecorder(stream);rec.ondataavailable=e=>e.data.size&&chunks.push(e.data);rec.onstop=async()=>{const type=rec.mimeType||chunks[0]?.type||'audio/webm',b=new Blob(chunks,{type});await put(k,b);a.src=URL.createObjectURL(b);a.hidden=false;pl.disabled=false;de.disabled=false;status.textContent='Recording saved on this device.';box.classList.remove('recording');stream?.getTracks().forEach(t=>t.stop());stream=null};rec.start();box.classList.add('recording');st.disabled=true;sp.disabled=false;status.textContent='Recording… tap Stop when finished.'}catch(e){box.classList.remove('recording');stream?.getTracks().forEach(t=>t.stop());stream=null;say(location.protocol==='https:'||location.hostname==='localhost'?'Microphone unavailable. Allow microphone access in browser settings.':'Microphone recording requires an HTTPS hosted app.')}};sp.onclick=()=>{if(rec?.state==='recording'){rec.stop();st.disabled=false;sp.disabled=true}};pl.onclick=()=>a.play();de.onclick=async()=>{await del(k);a.pause();a.hidden=true;a.removeAttribute('src');pl.disabled=true;de.disabled=true;status.textContent='Recording deleted.'}}
function bindHelp(){document.querySelectorAll('.helpWord').forEach(e=>e.onclick=ev=>wordPopup(e.dataset.word||e.textContent,ev))}function wordPopup(w,e){const x=DICT[String(w).toLowerCase()];if(!x)return;popup.innerHTML=`<button class="ghost" id="closePop" style="float:right">×</button><h3>${esc(x.word)}</h3><small>${esc(x.pos)}</small><p>${esc(x.definition)}</p><small>${esc(x.example)}</small><div class="buttons"><button class="secondary" id="sayWord">Listen</button><button class="ghost" id="saveWord">${state.vocab.includes(x.word.toLowerCase())?'Saved':'Add to vocabulary'}</button></div>`;popup.style.left=Math.min(innerWidth-345,Math.max(10,e.clientX+10))+'px';popup.style.top=Math.min(innerHeight-250,Math.max(75,e.clientY+10))+'px';popup.hidden=false;$('closePop').onclick=()=>popup.hidden=true;$('sayWord').onclick=()=>speak(x.word);$('saveWord').onclick=()=>{toggleWord(x.word.toLowerCase());$('saveWord').textContent=state.vocab.includes(x.word.toLowerCase())?'Saved':'Add to vocabulary'}}function toggleWord(w){state.vocab.includes(w)?state.vocab=state.vocab.filter(x=>x!==w):state.vocab.push(w);save();say('Vocabulary updated.')}
function openDictionary(){drawer.classList.add('open');drawer.innerHTML=`<div style="display:flex;justify-content:space-between"><div><div class="eyebrow">Learner dictionary</div><h2>Dictionary</h2></div><button class="ghost" id="closeDraw">×</button></div><div class="field" style="margin-top:15px"><label>Search</label><input id="dictSearch" placeholder="Course word or phrasal verb"></div><div id="dictResults"><div class="notice" style="margin-top:12px">This offline dictionary covers core course vocabulary. Sound plays only when you press Listen.</div></div>`;$('closeDraw').onclick=()=>drawer.classList.remove('open');$('dictSearch').oninput=()=>{const q=$('dictSearch').value.toLowerCase().trim(),r=Object.values(DICT).filter(x=>x.word.includes(q)||x.definition.includes(q)).slice(0,20);$('dictResults').innerHTML=r.map(x=>`<div class="dictEntry"><h3>${esc(x.word)}</h3><small>${esc(x.pos)}</small><p>${esc(x.definition)}</p><div class="buttons"><button class="secondary" data-say="${esc(x.word)}">Listen</button><button class="ghost" data-save="${esc(x.word.toLowerCase())}">${state.vocab.includes(x.word.toLowerCase())?'Saved':'Add'}</button></div></div>`).join('')||'<div class="notice" style="margin-top:12px">No local entry found.</div>';document.querySelectorAll('[data-say]').forEach(b=>b.onclick=()=>speak(b.dataset.say));document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{toggleWord(b.dataset.save);b.textContent=state.vocab.includes(b.dataset.save)?'Saved':'Add'})}}
function vocabView(){announceView('progress');const a=state.vocab.map(w=>DICT[w]).filter(Boolean);screen.innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">Personal notebook</div><h1>My vocabulary</h1><p class="lead">Review saved words and pronunciation.</p></section><section class="card" style="margin-top:16px">${a.length?a.map(x=>`<div class="dictEntry"><h3>${esc(x.word)}</h3><p>${esc(x.definition)}</p><button class="secondary" data-say="${esc(x.word)}">Listen</button></div>`).join(''):'<div class="notice">No saved words yet.</div>'}</section></div>`;document.querySelectorAll('[data-say]').forEach(b=>b.onclick=()=>speak(b.dataset.say))}
function buildExam(id){const l=level(id),items=l.units.flatMap((u,i)=>{const q=u.lessons[0].quiz;return[q[i%q.length],q[(i+2)%q.length]]}).slice(0,20);return{level:id,items,answers:{},marked:{},i:0,time:2700,started:false,submitted:false,writing:'',writingTask:l.units.at(-1).lessons.at(-1).writing,speakingTask:l.units.at(-1).lessons.at(-1).speaking}}
function examStart(id){announceView('more');if(!exam||exam.level!==id)exam=buildExam(id);const l=level(id);if(!exam.started){screen.innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">${l.cefr} formal assessment</div><h1>${esc(l.name)} end-of-level exam</h1><p class="lead">20 objective questions, writing and recorded speaking. Dictionary and Word Help are disabled.</p><div class="buttons"><button class="primary" id="startExam">Start 45-minute exam</button><button class="ghost" id="backCourse">Course map</button></div></section></div>`;$('startExam').onclick=()=>{exam.started=true;examQuestion()};$('backCourse').onclick=()=>go('course')}else exam.submitted?examResult():examQuestion()}
function tick(){clearInterval(timer);timer=setInterval(()=>{exam.time--;const e=document.getElementById('timer');if(e)e.textContent=fmt(exam.time);if(exam.time<=0)submitExam()},1000)}function fmt(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function examQuestion(){tick();const q=exam.items[exam.i];screen.innerHTML=`<div class="shell"><section class="card"><div style="display:flex;justify-content:space-between"><div><div class="eyebrow">Formal exam</div><h2>Question ${exam.i+1} of ${exam.items.length}</h2></div><div class="timer" id="timer">${fmt(exam.time)}</div></div><div class="examNav">${exam.items.map((_,i)=>`<button data-q="${i}" class="${exam.answers[i]!==undefined?'answered':''} ${exam.marked[i]?'marked':''}">${i+1}</button>`).join('')}</div><div class="quizItem"><h3>${esc(q.prompt)}</h3><div class="options">${q.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" ${exam.answers[exam.i]===i?'checked':''}><span><b>${String.fromCharCode(65+i)}.</b> ${esc(o)}</span></label>`).join('')}</div></div><label><input id="mark" type="checkbox" ${exam.marked[exam.i]?'checked':''}> Mark for review / not sure</label><div class="buttons"><button class="ghost" id="prev" ${exam.i===0?'disabled':''}>Previous</button><button class="secondary" id="review">Review</button><button class="primary" id="next">${exam.i===exam.items.length-1?'Review':'Next'}</button></div></section></div>`;document.querySelectorAll('[name=answer]').forEach(r=>r.onchange=()=>exam.answers[exam.i]=Number(r.value));$('mark').onchange=()=>exam.marked[exam.i]=$('mark').checked;document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{exam.i=Number(b.dataset.q);examQuestion()});$('prev').onclick=()=>{exam.i--;examQuestion()};$('next').onclick=()=>{exam.i<exam.items.length-1?(exam.i++,examQuestion()):examReview()};$('review').onclick=examReview}
function examReview(){clearInterval(timer);screen.innerHTML=`<div class="shell"><section class="card"><div class="eyebrow">Review</div><h1>Objective section</h1><div class="metrics"><div class="metric"><small>Answered</small><strong>${Object.keys(exam.answers).length}</strong></div><div class="metric"><small>Unanswered</small><strong>${exam.items.length-Object.keys(exam.answers).length}</strong></div><div class="metric"><small>Marked</small><strong>${Object.values(exam.marked).filter(Boolean).length}</strong></div><div class="metric"><small>Time</small><strong>${fmt(exam.time)}</strong></div></div><div class="buttons"><button class="ghost" id="returnQ">Return</button><button class="primary" id="production">Writing and speaking</button></div></section></div>`;$('returnQ').onclick=examQuestion;$('production').onclick=examProduction}
function examProduction(){screen.innerHTML=`<div class="shell"><section class="card"><div class="eyebrow">Productive skills</div><h1>Writing and speaking</h1><div class="writingBox"><h3>Writing</h3><p>${esc(exam.writingTask)}</p><textarea id="examWriting">${esc(exam.writing)}</textarea></div>${recordBox('exam-'+exam.level+'-speaking',exam.speakingTask)}<div class="buttons"><button class="ghost" id="backReview">Objective review</button><button class="primary" id="submit">Submit exam</button></div></section></div>`;bindRecord(document.querySelector('.recordBox'));$('examWriting').oninput=()=>exam.writing=$('examWriting').value;$('backReview').onclick=examReview;$('submit').onclick=submitExam}
function submitExam(){clearInterval(timer);exam.submitted=true;const c=exam.items.filter((q,i)=>exam.answers[i]===q.answer).length,p=Math.round(c/exam.items.length*100);state.exams[exam.level]={at:new Date().toISOString(),correct:c,total:exam.items.length,percent:p,answers:exam.answers,writing:exam.writing,speakingKey:'exam-'+exam.level+'-speaking',status:'Pending writing and speaking review'};log('exam-submitted',{level:exam.level,percent:p});examResult()}
function examResult(){const r=state.exams[exam.level],l=level(exam.level);screen.innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">${l.cefr} exam submitted</div><h1>Objective score: ${r.percent}%</h1><p class="lead">Writing and speaking are pending teacher or AI review.</p><div class="buttons"><button class="primary" id="downloadExam">Download exam package</button><button class="secondary" id="sendExam">Submit to teacher</button><button class="ghost" id="dash">Dashboard</button></div></section></div>`;$('downloadExam').onclick=()=>exportPackage('exam',exam.level);$('sendExam').onclick=()=>sendTeacher('exam',exam.level);$('dash').onclick=dashboard}
function progressView(){announceView('progress');const l=level(state.level),p=prog(l.id),examRows=Object.entries(state.exams||{}).map(([id,r])=>`<div class="examResultRow"><div><b>${esc(level(id).cefr)} exam</b><br><small>${esc(r.status||'Submitted')}</small></div><strong>${Number.isFinite(Number(r.percent))?r.percent+'%':'—'}</strong></div>`).join('');screen.innerHTML=`<div class="shell"><section class="hero"><div class="progressHero"><div class="progressRing" style="--progress:${p.p}%"><strong>${p.p}%</strong></div><div><div class="eyebrow">Learning progress</div><h1>${esc(l.cefr)} • ${esc(l.name)}</h1><p class="lead">${p.n} of ${p.total} lessons completed. ${state.vocab.length} vocabulary items saved.</p></div></div></section><section class="card" style="margin-top:14px"><div class="mobileSectionTitle"><h2>Backups and results</h2><small>Keep your work safe</small></div><div class="mobileActionGrid"><button class="mobileActionCard primaryCard" id="progressBackup"><b>Export backup</b><small>Download lessons, writing, exams and recordings.</small></button><label class="mobileActionCard" for="progressRestore"><b>Restore backup</b><small>Move your saved work back onto this device.</small><input id="progressRestore" type="file" accept=".zip,.json" hidden></label><button class="mobileActionCard" id="protectStorage"><b>Protect local data</b><small>Ask the browser to keep app storage when space is low.</small></button><button class="mobileActionCard" id="openWords"><b>Vocabulary notebook</b><small>Review ${state.vocab.length} saved words.</small></button></div></section><section class="card" style="margin-top:14px"><h2>Exam history</h2><div class="examResultList" style="margin-top:13px">${examRows||'<div class="notice">No end-of-level exam has been submitted yet.</div>'}</div></section></div>`;$('progressBackup').onclick=exportBackup;$('progressRestore').onchange=e=>restoreBackup(e.target.files[0]);$('openWords').onclick=()=>go('vocab');$('protectStorage').onclick=async()=>{if(window.EnglishPathwaysMobile?.requestPersistentStorage){const ok=await window.EnglishPathwaysMobile.requestPersistentStorage();say(ok?'Browser storage protection is enabled or granted.':'The browser did not grant persistent storage. Backups remain important.')}else say('Storage protection is unavailable in this browser.')}}
function moreView(){announceView('more');const l=level(state.level),hasPlacement=Boolean(localStorage.getItem('english-placement-test-state-v2'));screen.innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">Tools and settings</div><h1>More</h1><p class="lead">Assessment, updates, installation and help.</p></section><section class="card" style="margin-top:14px"><div class="mobileActionGrid"><button class="mobileActionCard primaryCard" id="moreExam"><b>${esc(l.cefr)} end-of-level exam</b><small>Timed objective section, writing and recorded speaking.</small></button><button class="mobileActionCard" id="morePlacement"><b>Placement test</b><small>Open the comprehensive placement assessment.</small></button><button class="mobileActionCard" id="morePlacementExport" ${hasPlacement?'':'disabled'}><b>Export placement progress</b><small>${hasPlacement?'Save the current placement-test answers and position to a transfer file.':'No saved placement-test progress was found on this device.'}</small></button><button class="mobileActionCard" id="morePlacementImport"><b>Import placement progress</b><small>Restore a placement-progress file from another computer or phone.</small></button><input id="placementProgressFile" type="file" accept=".json,application/json" hidden><button class="mobileActionCard" id="moreUpdates"><b>Course updates</b><small>Install an official lesson content pack.</small></button><button class="mobileActionCard" id="moreInstall"><b>Install this app</b><small>Add English Pathways to the phone Home Screen.</small></button><button class="mobileActionCard" id="moreTheme"><b>Appearance</b><small>Switch between light and dark mode.</small></button><button class="mobileActionCard" id="moreGuide"><b>Arabic student guide</b><small>Open the Arabic operating guide included with the app.</small></button></div></section><section class="card" style="margin-top:14px"><h2>About this edition</h2><p>Mobile App Edition ${esc(C.mobileEdition||'1.0')} • Course ${esc(D.version)} • ${D.lessonCount} lessons.</p><div class="notice">Placement progress transfer is stored only on the device where you import it. It does not change other students' copies of the app.</div></section></div>`;$('moreExam').onclick=()=>go('exam',{level:state.level});$('morePlacement').onclick=()=>window.open('placement-test/index.html','_blank');$('morePlacementExport').onclick=exportPlacementProgress;$('morePlacementImport').onclick=()=>$('placementProgressFile').click();$('placementProgressFile').onchange=e=>importPlacementProgress(e.target.files[0]);$('moreUpdates').onclick=()=>go('updates');$('moreInstall').onclick=()=>window.EnglishPathwaysMobile?.installApp?.();$('moreTheme').onclick=()=>{$('themeBtn')?.click();moreView()};$('moreGuide').onclick=()=>window.open('دليل_الطالب_بالعربية.html','_blank')}
function updatesView(){announceView('more');const packs=contentPacks();screen.innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">Course content manager</div><h1>Install lesson updates</h1><p class="lead">Future course packs can add units, lessons and dictionary entries without deleting completed work.</p><div class="metrics"><div class="metric"><small>Application version</small><strong>${esc(C.version)}</strong></div><div class="metric"><small>Course version</small><strong>${esc(D.version)}</strong></div><div class="metric"><small>Available lessons</small><strong>${D.lessonCount}</strong></div><div class="metric"><small>Installed packs</small><strong>${packs.length}</strong></div></div><div class="notice warn"><b>Before installing:</b> export a progress backup. Only install official English Pathways JSON content packs supplied by the teacher.</div><div class="field" style="margin-top:18px"><label>Course content pack (.json)</label><input id="contentPackFile" type="file" accept=".json"></div><div class="buttons"><button class="primary" id="installPack">Install selected update</button><button class="secondary" id="exportBeforeUpdate">Export backup first</button><button class="ghost" id="returnAfterUpdate">Return to dashboard</button></div></section><section class="card" style="margin-top:16px"><h2>Installed content packs</h2>${packs.length?packs.map(p=>`<div class="lessonRow"><div class="num">✓</div><div><b>${esc(p.title||p.contentPackVersion)}</b><br><small>${esc(p.contentPackVersion||'Unknown version')} • ${esc(p.installedAt||'Installed')}</small></div><span>Active</span></div>`).join(''):'<div class="notice" style="margin-top:14px">No separate update packs are installed. Version 2.0 already includes the expanded core curriculum.</div>'}<p><small>Updates add content; they do not overwrite existing answers or completed-lesson records. Removing a pack is intentionally unavailable because it could hide lessons that contain student work.</small></p></section></div>`;$('installPack').onclick=()=>installContentPack($('contentPackFile').files[0]);$('exportBeforeUpdate').onclick=exportBackup;$('returnAfterUpdate').onclick=dashboard}
async function installContentPack(f){if(!f)return say('Select a JSON content pack first.');try{const pack=JSON.parse(await f.text());if(pack.platform!=='English Pathways'||!pack.contentPackVersion||(!Array.isArray(pack.addedUnits)&&!Array.isArray(pack.replaceUnits)))throw Error('This is not a recognised English Pathways content pack.');if(pack.minimumAppVersion&&compareVersions(C.version,pack.minimumAppVersion)<0)throw Error('This pack requires application version '+pack.minimumAppVersion+' or later.');const packs=contentPacks();if(packs.some(p=>p.contentPackVersion===pack.contentPackVersion))throw Error('This content pack is already installed.');pack.installedAt=new Date().toISOString();packs.push(pack);localStorage.setItem(PACKKEY,JSON.stringify(packs));applyContentPacks();log('content-pack-installed',{version:pack.contentPackVersion,title:pack.title||''});say('Content update installed.');setTimeout(updatesView,400)}catch(e){say('Update failed: '+e.message)}}
function gate(){if(admin)return go('admin');modal.innerHTML=`<div class="backdrop"><div class="modalBox"><div class="eyebrow">Administrator</div><h2>Enter password</h2><div class="field"><input id="pass" type="password"></div><div class="buttons"><button class="ghost" id="cancel">Cancel</button><button class="primary" id="unlock">Open admin</button></div><p><small>This is a local convenience gate, not strong server security. Change the password in config.js.</small></p></div></div>`;$('cancel').onclick=()=>modal.innerHTML='';$('unlock').onclick=()=>{if($('pass').value===C.adminPassword){admin=true;modal.innerHTML='';go('admin')}else say('Incorrect password.')}}

const PLACEMENT_STATE_KEY='english-placement-test-state-v2';
function exportPlacementProgress(){
  try{
    const raw=localStorage.getItem(PLACEMENT_STATE_KEY);
    if(!raw)throw new Error('No saved placement-test progress was found on this device.');
    const placementState=JSON.parse(raw);
    const payload={type:'english-pathways-placement-progress',formatVersion:1,exportedAt:new Date().toISOString(),courseVersion:D.version,placementState};
    const candidate=placementState?.candidate?.name||state.profile.name||'student';
    download(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),safe(candidate)+'_Placement_Progress.json');
    say('Placement progress exported.');
  }catch(e){say('Export failed: '+e.message)}
}
async function importPlacementProgress(file){
  if(!file)return;
  try{
    const payload=JSON.parse(await file.text());
    const imported=payload?.type==='english-pathways-placement-progress'?payload.placementState:(payload?.placementState||payload);
    if(!imported||typeof imported!=='object'||typeof imported.started!=='boolean'||!imported.responses||typeof imported.responses!=='object')throw new Error('This is not a recognised placement-progress file.');
    const current=localStorage.getItem(PLACEMENT_STATE_KEY);
    if(current)localStorage.setItem(PLACEMENT_STATE_KEY+'-before-import',current);
    const restored={...imported};
    if(!restored.finished){restored.paused=false;restored.viewingResultsSectionIndex=null}
    localStorage.setItem(PLACEMENT_STATE_KEY,JSON.stringify(restored));
    say('Placement progress imported. Opening the test…');
    setTimeout(()=>window.open('placement-test/index.html','_self'),500);
  }catch(e){say('Import failed: '+e.message)}
}
function adminView(tab='overview'){if(!admin)return gate();screen.innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">Teacher and administrator</div><h1>Administration</h1><p class="lead">Manage levels, placement import, teacher submission, data and reusable AI prompts.</p></section><section class="card" style="margin-top:16px"><div class="adminTabs">${['overview','levels','submission','prompts','data'].map(t=>`<button data-tab="${t}" class="${t===tab?'active':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div id="adminContent">${adminHtml(tab)}</div></section></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>adminView(b.dataset.tab));bindAdmin(tab)}
function adminHtml(t){if(t==='overview')return`<div class="grid2"><div class="notice"><h3>Placement result import</h3><p>Import JSON or the placement-test ZIP. The recommendation is provisional until writing and speaking are reviewed.</p><input id="placementFile" type="file" accept=".json,.zip"><div id="placementStatus"></div></div><div class="notice"><h3>Current recommendation</h3><p>${state.recommendation?esc(state.recommendation):'None imported.'}</p><button class="secondary" id="applyRec" ${state.recommendation?'':'disabled'}>Apply recommendation</button></div></div>`;if(t==='levels')return`${D.levels.map(l=>`<div class="lessonRow"><div class="num">${l.cefr}</div><div><b>${esc(l.name)}</b><br><small>${prog(l.id).p}% complete</small></div><label><input type="checkbox" data-unlock="${l.id}" ${unlocked(l.id)?'checked':''}> Unlocked</label></div>`).join('')}<div class="field" style="margin-top:15px"><label>Current level</label><select id="currentLevel">${D.levels.map(l=>`<option value="${l.id}" ${state.level===l.id?'selected':''}>${l.cefr} — ${esc(l.name)}</option>`).join('')}</select></div>`;if(t==='submission')return`<h2>Teacher email submission</h2><p>Deploy the included Google Apps Script and paste its Web App URL.</p><div class="field"><label>Web App URL</label><input id="endpoint" value="${esc(state.endpoint)}"></div><div class="buttons"><button class="primary" id="saveEndpoint">Save</button></div><div class="notice warn" style="margin-top:15px">Large audio packages may exceed free service limits. ZIP download remains the backup.</div>`;if(t==='prompts')return`<h2>AI prompt library</h2><p>Upload the relevant ZIP to a new ChatGPT conversation, then copy the matching prompt.</p>${Object.entries(P).map(([n,x],i)=>`<div class="promptCard"><h3>${esc(n)}</h3><pre>${esc(x)}</pre><button class="secondary" data-copy="${i}">Copy prompt</button></div>`).join('')}`;return`<div class="grid2"><div class="notice"><h3>Backup and restore</h3><div class="buttons"><button class="primary" id="exportAll">Export backup</button><label class="secondary"><input id="restore" type="file" accept=".zip,.json" hidden>Restore backup</label></div></div><div class="notice warn"><h3>Reset</h3><button class="danger" id="reset">Delete all local progress</button></div></div>`}
function bindAdmin(t){if(t==='overview'){$('placementFile').onchange=e=>importPlacement(e.target.files[0]);$('applyRec').onclick=()=>{const l=D.levels.find(x=>x.id===state.recommendation);if(l){state.level=l.id;state.unlocked=D.levels.slice(0,idx(l.id)+1).map(x=>x.id);state.current=l.units[0].lessons[0].id;save();say('Recommendation applied.')}}}if(t==='levels'){document.querySelectorAll('[data-unlock]').forEach(c=>c.onchange=()=>{c.checked&&!unlocked(c.dataset.unlock)?state.unlocked.push(c.dataset.unlock):!c.checked&&(state.unlocked=state.unlocked.filter(x=>x!==c.dataset.unlock));save()});$('currentLevel').onchange=()=>{state.level=$('currentLevel').value;if(!unlocked(state.level))state.unlocked.push(state.level);state.current=level(state.level).units[0].lessons[0].id;save();say('Current level changed.')}}if(t==='submission')$('saveEndpoint').onclick=()=>{state.endpoint=$('endpoint').value.trim();save();say('Endpoint saved.')};if(t==='prompts'){const a=Object.values(P);document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{await navigator.clipboard.writeText(a[Number(b.dataset.copy)]);say('Prompt copied.')} )}if(t==='data'){$('exportAll').onclick=exportBackup;$('restore').onchange=e=>restoreBackup(e.target.files[0]);$('reset').onclick=()=>{if(confirm('Delete all local progress?')){localStorage.removeItem(SKEY);localStorage.removeItem(PACKKEY);indexedDB.deleteDatabase(DB);state=fresh();admin=false;render()}}}}
async function importPlacement(f){if(!f)return;try{let d;if(f.name.endsWith('.zip')){const z=await JSZip.loadAsync(f);let target;z.forEach((p,o)=>{if(/(results_with_answer_key|answers_with_key|completed_responses|responses)\.json$/.test(p))target=o});if(!target)throw Error('No recognised results JSON');d=JSON.parse(await target.async('text'))}else d=JSON.parse(await f.text());const s=[];(d.sections||[]).forEach(x=>{if(x.score&&Number.isFinite(Number(x.score.percentage)))s.push(Number(x.score.percentage))});if(!s.length)throw Error('No objective scores');const a=s.reduce((x,y)=>x+y,0)/s.length;state.recommendation=a<30?'A1':a<45?'A2':a<60?'B1':a<72?'B2_1':a<82?'B2_2':a<90?'C1_1':'C1_2';save();$('placementStatus').innerHTML=`<p>Objective average: <b>${Math.round(a)}%</b>. Provisional recommendation: <b>${level(state.recommendation).cefr} — ${esc(level(state.recommendation).name)}</b>.</p>`}catch(e){$('placementStatus').textContent='Import failed: '+e.message}}
function audioExt(b){const t=(b?.type||'').toLowerCase();if(t.includes('mp4')||t.includes('m4a'))return'.m4a';if(t.includes('ogg'))return'.ogg';if(t.includes('wav'))return'.wav';return'.webm'}async function packageZip(kind='progress',id=null){const z=new JSZip(),payload={platform:{title:D.title,version:D.version,appVersion:C.version,mobileEdition:C.mobileEdition||null},kind,exportedAt:new Date().toISOString(),state,contentPacks:contentPacks()};if(kind==='exam')payload.exam=state.exams[id];z.file('progress.json',JSON.stringify(payload,null,2));z.file('AI_REVIEW_PROMPT.txt',kind==='exam'?P['End-of-level exam grading prompt']:P['Course-progress review prompt']);z.file('README.txt','Upload this ZIP to ChatGPT and paste AI_REVIEW_PROMPT.txt. Audio may be WebM, M4A, OGG or WAV depending on the phone/browser.');const rf=z.folder('recordings'),all=await keys(),wanted=kind==='exam'&&state.exams[id]?.speakingKey?[state.exams[id].speakingKey]:all;for(const k of wanted){const b=await get(k);if(b)rf.file(safe(k)+audioExt(b),b)}return z}async function exportBackup(){say('Preparing backup…');const z=await packageZip();download(await z.generateAsync({type:'blob',compression:'DEFLATE'}),safe(state.profile.name)+'_English_Pathways_Backup.zip');say('Backup downloaded.')}async function exportPackage(k,id){say('Preparing exam package…');const z=await packageZip(k,id);download(await z.generateAsync({type:'blob',compression:'DEFLATE'}),safe(state.profile.name)+'_'+id+'_Exam.zip')}
async function restoreBackup(f){if(!f)return;try{let d;if(f.name.endsWith('.zip')){const z=await JSZip.loadAsync(f),p=z.file('progress.json');if(!p)throw Error('progress.json not found');d=JSON.parse(await p.async('text'))}else d=JSON.parse(await f.text());state={...fresh(),...(d.state||d)};if(Array.isArray(d.contentPacks))localStorage.setItem(PACKKEY,JSON.stringify(d.contentPacks));save();say('Backup restored. Reloading course content…');setTimeout(()=>location.reload(),500)}catch(e){say('Restore failed: '+e.message)}}
async function sendTeacher(kind,id){if(!state.endpoint)return say('Teacher submission is not configured. Download the ZIP instead.');if(!navigator.onLine)return say('You are offline. Connect to the internet, then submit again.');try{say('Preparing and uploading submission…');const z=await packageZip(kind,id),b64=await z.generateAsync({type:'base64'}),stamp=new Date().toISOString().replace(/[:.]/g,'-'),payload={studentName:state.profile.name,studentEmail:state.profile.email,kind,level:id||state.level,filename:safe(state.profile.name)+'_'+(id||state.level)+'_'+kind+'_'+stamp+'.zip',fileBase64:b64};await fetch(state.endpoint,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain'},body:JSON.stringify(payload)});say('Submission sent. Keep the downloaded ZIP until the teacher confirms receipt.')}catch(e){say('Submission failed. Download the ZIP and send it manually.')}}
window.EnglishPathways={go,openDictionary,exportBackup,restoreBackup,sendTeacher,say,getState:()=>state};render();})();
